#!/usr/bin/env python3
"""Find the actual deck-module quotient generated by the cubic obstruction."""
import numpy as np,json
from pathlib import Path
f=Path(__file__).with_name('check_cubic_centralizer_homology')
A=np.load(f.with_suffix('.npz'));j=json.loads(f.with_suffix('.json').read_text())
Z=A['cycle31'];P=A['projection31']
def mul(a,b):return tuple(sum(a[2*i+k]*b[2*k+l] for k in range(2))%3 for i in range(2) for l in range(2))
def inv(a):return a[3],-a[1]%3,-a[2]%3,a[0]
U=(1,1,0,1);L=(1,0,2,1);I=(1,0,0,1)
def band(i,j):return tuple(range(j-1,i,-1))+(i,i)+tuple(-k for k in range(i+1,j))
def evaluate(w):
 q=I
 for i in w:q=mul(q,(U,L,U)[i-1] if i>0 else inv((U,L,U)[-i-1]))
 return q
gens=[evaluate(band(i,j)) for i,j in ((1,3),(2,3),(1,4),(2,4),(3,4))]
Q=[I];idx={I:0}
for q in Q:
 for g in gens:
  h=mul(q,g)
  if h not in idx:idx[h]=len(Q);Q.append(h)
assert len(Q)==24
actions=[]
for q in Q:
 D=np.zeros((120,120),dtype=np.int16)
 for h in range(24):
  for k in range(5):D[5*h+k,5*idx[mul(q,Q[h])]+k]=1
 actions.append(Z@D@P%3)
# The chosen obstruction column is supported in the odd total-linking block.
ell=A['coker'][102:114,35]
assert np.array_equal(ell,np.array([2,1,2,1,0,1,0,0,0,0,0,0]))
rows=np.array([M@ell for M in actions],dtype=np.int16)%3;r=0
for c in range(12):
 nz=np.flatnonzero(rows[r:,c])
 if not len(nz):continue
 k=r+int(nz[0]);rows[[r,k]]=rows[[k,r]];rows[r]=rows[r]*pow(int(rows[r,c]),-1,3)%3
 ns=np.flatnonzero(rows[:,c]);ns=ns[ns!=r];rows[ns]=(rows[ns]-rows[ns,c,None]*rows[r])%3;r+=1
print('Deck-invariant dual module generated by the obstruction: dimension',r)
print('Basis:',rows[:r].tolist())
np.savez_compressed(Path(__file__).with_suffix('.npz'),actions=np.array(actions),dual_basis=rows[:r])
Path(__file__).with_suffix('.json').write_text(json.dumps({'dimension':r,'dual_basis':rows[:r].tolist()},indent=2)+'\n')
